'use strict';
// This fluid balance illustrates assumptions; it is not part of any fitted price model.
function householdState(z,day){
 const initial=z.arrivals*z.buffer,deficit=Math.max(0,z.arrivals-z.capacity),during=Math.min(day,z.days),after=Math.max(0,day-z.days);
 const backlog=Math.max(0,deficit*during-(20-z.arrivals)*after);
 const drawn=Math.min(initial,deficit*during),recovered=Math.min(deficit*z.days,(20-z.arrivals)*after);
 const stock=Math.min(initial,Math.max(0,initial-drawn+recovered)),inDisruption=day<z.days;
 const shortage=inDisruption&&stock<=1e-8?deficit:0,delivery=z.arrivals-shortage,fraction=initial>0?stock/initial:0;
 const pressure=shortage>0?'Supply-gap pressure':inDisruption&&deficit>0&&fraction<.25?'Low-buffer pressure':!inDisruption&&backlog>0?'Pressure easing':'Flow supported';
 return {stock,fraction,backlog,delivery,shortage,pressure,inDisruption,day};
}
function prepareHouseholdFlow(s){
 $('householdFlow').innerHTML=`<p class="eyebrow">FROM THE HARBOUR TO EVERYDAY LIFE / ASSUMED MECHANISM</p><h3>The tank buys time. It does not make new oil.</h3><p id="supplyPhase"></p><label class="small">Explore the sequence · 80-second playback<input id="shipTimeline" type="range" min="0" max="100" value="0" step="0.1" aria-label="Supply-chain timeline" style="width:100%"></label><svg viewBox="0 0 1000 285" role="img" aria-label="Illustrative storage tank supplies refining and distribution, then fuel stations, freight and homes"><defs><marker id="flowArrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#8ba99c"/></marker></defs><path d="M35 150H105 M230 150H360 M490 150H585 M585 150V58H730 M585 150H730 M585 150V245H730" fill="none" stroke="#8ba99c" stroke-width="4" marker-end="url(#flowArrow)"/><text x="20" y="115" font-size="15">Ships</text><rect x="110" y="52" width="110" height="180" rx="12" fill="white" stroke="#78978c" stroke-width="2"/><rect id="homeTankFill" x="115" y="57" width="100" height="170" rx="8" fill="#72a69c"/><ellipse cx="165" cy="52" rx="55" ry="13" fill="#d5e4dc" stroke="#78978c"/><text id="homeTankLabel" x="165" y="265" text-anchor="middle" font-size="16"></text><rect x="365" y="92" width="120" height="120" rx="9" fill="#d7e4dc" stroke="#78978c"/><path d="M385 92V47H403V92M425 92V65H443V92" fill="#a3beb0" stroke="#78978c"/><text x="425" y="139" text-anchor="middle" font-size="15">Refining &amp;</text><text x="425" y="161" text-anchor="middle" font-size="15">distribution</text><g fill="#087e83"><rect x="742" y="25" width="32" height="48" rx="4"/><path d="M774 36H784V70H792" fill="none" stroke="#087e83" stroke-width="4"/><rect x="742" y="132" width="49" height="27" rx="3"/><rect x="790" y="141" width="23" height="18" rx="3"/><circle cx="754" cy="165" r="7"/><circle cx="800" cy="165" r="7"/><path d="M740 240L770 211L800 240V269H740Z"/></g><g font-size="17" fill="#183737"><text x="830" y="53">Fuel stations</text><text x="830" y="155">Freight &amp; shops</text><text x="830" y="250">Homes &amp; travel</text></g><g id="deliveryParticles" fill="#087e83"></g></svg><div class="chain-readout"><div><span>SCENARIO BUFFER REMAINING</span><strong id="stockReadout"></strong><span>100% = the buffer you chose, not a real tank's capacity</span></div><div><span>CURRENT DAILY NEED MET</span><strong id="deliveryReadout"></strong><span>Arrivals are assumed equal to normal daily use</span></div><div><span>ILLUSTRATIVE PRICE PRESSURE</span><strong id="pressureReadout"></strong><span>Qualitative mechanism; no price or causal estimate</span></div></div><p id="pricePressureNote">Stocks cover delivery gaps; reopening replenishes them. Price pressure is illustrative, not a pump-price forecast. <a href="https://www.eia.gov/energyexplained/gasoline/factors-affecting-gasoline-prices.php" target="_blank" rel="noopener">EIA: what affects pump prices</a></p><details><summary>How to read this illustration</summary><p>Initial stock = arrivals × buffer days. During disruption, transit supplies daily need and stocks cover the gap until empty. After reopening, spare capacity serves delayed cargo and refills the buffer, capped at its initial amount. The whole disruption and queue-clearance period is compressed into 80 seconds, then held. Boat icons are visual samples, not one-for-one deliveries. Processing and travel lags are compressed; crude is not delivered directly to households. No live tank levels, AIS or retail-price data are used. All percentages describe this assumed scenario.</p></details>`;
 s.supplyEnd=Math.max(1,s.z.days+s.z.clear+3);s.supplyDuration=80;
 $('shipTimeline').oninput=()=>{shipManualPause=true;stopShipFrame();s.elapsed=Number($('shipTimeline').value)/100*s.supplyDuration;s.queueLayer.replaceChildren();s.trafficLayer.replaceChildren();s.queue=[];s.moving=[];s.served=0;s.nextArrival=s.elapsed+s.arrivalGap;s.nextRelease=s.elapsed+.45;const v=householdState(s.z,s.elapsed/s.supplyDuration*s.supplyEnd);for(let i=0;i<Math.min(15,Math.ceil(v.backlog));i++)enqueueBoat(s);renderShipFrame(s,0);updatePlaybackButton();};
}
function renderHouseholdFlow(s){
 const day=Math.min(s.supplyEnd,s.elapsed/s.supplyDuration*s.supplyEnd),z=s.z,v=householdState(z,day),fill=$('homeTankFill');if(!fill)return;
 $('shipTimeline').value=String(Math.min(100,s.elapsed/s.supplyDuration*100));
 fill.setAttribute('y',String(227-170*v.fraction));fill.setAttribute('height',String(170*v.fraction));fill.setAttribute('fill',v.fraction<.25?'#b66e46':'#72a69c');
 $('homeTankLabel').textContent=`${Math.round(100*v.fraction)}% of chosen buffer`;
 $('stockReadout').textContent=`${Math.round(100*v.fraction)}%`;$('deliveryReadout').textContent=`${Math.round(100*v.delivery/z.arrivals)}%`;$('pressureReadout').textContent=v.pressure;$('pressureReadout').style.color=v.shortage>0?'#a9582d':'#087e83';
 $('supplyPhase').textContent=`Illustrative day ${fmt(day,1)} · ${v.inDisruption?'Route disrupted':v.backlog>0?'Route reopened · buffer refilling':'Flow restored'}${s.elapsed>=s.supplyDuration?' · Replay to start again':''}`;
 if($('liveBufferLabel'))$('liveBufferLabel').textContent=`${Math.round(100*v.fraction)}% of chosen buffer · now`;
 s.svg.querySelectorAll('.live-buffer-fill').forEach(el=>{el.setAttribute('y',String(248-126*v.fraction));el.setAttribute('height',String(126*v.fraction));el.setAttribute('fill',v.fraction<.25?'#b66e46':'#72a69c');});
 const open=v.inDisruption?z.open:100,gate=50+open*1.2;
 $('shipGate').setAttribute('y1',String(180-gate/2));$('shipGate').setAttribute('y2',String(180+gate/2));
 $('shipShoalTop').setAttribute('d',`M420 55 L550 55 L525 ${180-gate/2} L445 ${180-gate/2} Z`);
 $('shipShoalBottom').setAttribute('d',`M420 305 L550 305 L525 ${180+gate/2} L445 ${180+gate/2} Z`);
 $('shipCapacityLabel').textContent=`${fmt(v.inDisruption?z.capacity:20,1)} vessels/day now · ${v.inDisruption?'disrupted':'route reopened'}`;
 $('shipQueueLabel').textContent=`Current backlog ${fmt(v.backlog,0)} · sample icons`;
 s.svg.dataset.bufferFraction=v.fraction.toFixed(6);s.svg.dataset.supplyDay=day.toFixed(3);s.svg.dataset.deliveryFraction=(v.delivery/z.arrivals).toFixed(6);
 const layer=$('deliveryParticles');layer.replaceChildren();layer.setAttribute('fill',v.shortage>0?'#b66e46':'#087e83');
 const paths=[[[235,150],[585,150],[585,58],[725,58]],[[235,150],[725,150]],[[235,150],[585,150],[585,245],[725,245]]];
 paths.forEach((points,k)=>{const lengths=points.slice(1).map((p,i)=>Math.hypot(p[0]-points[i][0],p[1]-points[i][1])),total=lengths.reduce((a,b)=>a+b,0);for(let j=0;j<4;j++){if(j/4>=v.delivery/z.arrivals)continue;let distance=((s.elapsed/9+j/4+k*.1)%1)*total,i=0;while(i<lengths.length-1&&distance>lengths[i])distance-=lengths[i++];const f=distance/lengths[i],p=points[i],q=points[i+1],dot=document.createElementNS(SVG_NS,'circle');dot.setAttribute('r','5');dot.setAttribute('cx',String(p[0]+(q[0]-p[0])*f));dot.setAttribute('cy',String(p[1]+(q[1]-p[1])*f));layer.append(dot);}});
}
